                  const isPresetDisabled =
                    isDisabled ||
                    !isRangeWithinSpan(
                      presetRange,
                      maxRangeSpan,
                      minRangeSpan,
                    ) ||
                    isDateDisabled(plainDateFromISO(presetRange.start)) ||
                    isDateDisabled(plainDateFromISO(presetRange.end));
