/** The parts of `formatCalendarDate`'s label. */
export function formatCalendarDateToParts(
  calendar: CalendarSystem,
  pd: PlainDate,
  options: Intl.DateTimeFormatOptions,
  locale: Locale,
  {relatedYear = false}: {readonly relatedYear?: boolean} = {},
