// Returns `parts` itself where Intl already names Temporal's month and day.
function withTemporalDay(
  calendar: CalendarSystem,
  pd: PlainDate,
  parts: Intl.DateTimeFormatPart[],
  options: Intl.DateTimeFormatOptions,
  locale: Locale,
