    return parts;
  }
  const {numberingSystem} = dateTimeFormatFor(locale, {
    ...options,
    calendar,
    timeZone: 'UTC',
  }).resolvedOptions();
  const middleValues = new Map(
    middleParts.map(part => [part.type, part.value]),
  );
